import Foundation

public struct OAuthTokenSet: Codable, Sendable, Equatable { public let accessToken:String; public let refreshToken:String?; public let expiresAt:Date?; public let scopes:Set<String>; public init(accessToken:String, refreshToken:String?=nil, expiresAt:Date?=nil, scopes:Set<String>=[]) { self.accessToken=accessToken; self.refreshToken=refreshToken; self.expiresAt=expiresAt; self.scopes=scopes }; public func needsRefresh(at date:Date=Date(), leeway:TimeInterval=300)->Bool { guard let expiresAt else { return false }; return expiresAt.timeIntervalSince(date) <= leeway } }
public protocol OAuthTokenStoring: Sendable { func load(provider:String) async throws -> OAuthTokenSet?; func save(_ tokens:OAuthTokenSet, provider:String) async throws; func remove(provider:String) async throws }
public actor InMemoryOAuthTokenStore: OAuthTokenStoring { private var values:[String:OAuthTokenSet]=[:]; public init(){}; public func load(provider:String)->OAuthTokenSet?{values[provider]}; public func save(_ tokens:OAuthTokenSet, provider:String){values[provider]=tokens}; public func remove(provider:String){values.removeValue(forKey:provider)} }
public protocol OAuthRefreshing: Sendable { func refresh(_ tokens:OAuthTokenSet) async throws -> OAuthTokenSet }
public actor OAuthSession { private let provider:String; private let store:any OAuthTokenStoring; private let refresher:any OAuthRefreshing; public init(provider:String, store:any OAuthTokenStoring, refresher:any OAuthRefreshing){self.provider=provider;self.store=store;self.refresher=refresher}; public func validTokens(now:Date=Date()) async throws -> OAuthTokenSet { guard var tokens=try await store.load(provider:provider) else { throw ProviderAdapterError.authorizationRequired }; if tokens.needsRefresh(at:now){tokens=try await refresher.refresh(tokens);try await store.save(tokens,provider:provider)}; return tokens } }
